package importer

import (
	"encoding/csv"
	"errors"
	"fmt"
	"io"
	"strconv"
	"strings"
)

// Row is one stock line from an import file.
type Row struct {
	Name     string
	Quantity int
	Unit     string
}

// RowError reports a malformed row by its 1-based line number.
type RowError struct {
	Line int
	Err  error
}

func (e RowError) Error() string { return fmt.Sprintf("line %d: %v", e.Line, e.Err) }

// ReadStock parses `name,quantity,unit` rows. Malformed rows are skipped and returned as errors.
func ReadStock(r io.Reader) ([]Row, []RowError, error) {
	reader := csv.NewReader(r)
	reader.FieldsPerRecord = -1

	var rows []Row
	var bad []RowError

	for line := 1; ; line++ {
		record, err := reader.Read()
		if errors.Is(err, io.EOF) {
			return rows, bad, nil
		}
		if err != nil {
			return nil, nil, fmt.Errorf("reading stock csv: %w", err)
		}
		if len(record) != 3 {
			bad = append(bad, RowError{Line: line, Err: fmt.Errorf("want 3 fields, got %d", len(record))})
			continue
		}
		qty, err := strconv.Atoi(strings.TrimSpace(record[1]))
		if err != nil {
			bad = append(bad, RowError{Line: line, Err: fmt.Errorf("quantity %q: %w", record[1], err)})
			continue
		}
		rows = append(rows, Row{Name: strings.TrimSpace(record[0]), Quantity: qty, Unit: strings.TrimSpace(record[2])})
	}
}

package importer

import (
	"strings"
	"testing"
)

func TestReadStock(t *testing.T) {
	t.Parallel()

	t.Run("good rows", func(t *testing.T) {
		t.Parallel()
		rows, bad, err := ReadStock(strings.NewReader("Washer,200,pcs\nNut M6,50,boxes\n"))
		if err != nil || len(bad) != 0 {
			t.Fatalf("err=%v bad=%v", err, bad)
		}
		if len(rows) != 2 || rows[1] != (Row{Name: "Nut M6", Quantity: 50, Unit: "boxes"}) {
			t.Fatalf("rows = %+v", rows)
		}
	})

	t.Run("quoted comma in name", func(t *testing.T) {
		t.Parallel()
		rows, bad, err := ReadStock(strings.NewReader("\"Bolt, M6\",40,pcs\n"))
		if err != nil || len(bad) != 0 {
			t.Fatalf("err=%v bad=%v", err, bad)
		}
		if len(rows) != 1 || rows[0].Name != "Bolt, M6" || rows[0].Quantity != 40 {
			t.Fatalf("rows = %+v", rows)
		}
	})

	t.Run("short row skipped with line number", func(t *testing.T) {
		t.Parallel()
		rows, bad, err := ReadStock(strings.NewReader("Washer,200,pcs\nNut M6,50\n"))
		if err != nil {
			t.Fatal(err)
		}
		if len(rows) != 1 || len(bad) != 1 || bad[0].Line != 2 {
			t.Fatalf("rows=%+v bad=%+v", rows, bad)
		}
	})

	t.Run("non numeric quantity skipped", func(t *testing.T) {
		t.Parallel()
		rows, bad, err := ReadStock(strings.NewReader("Washer,lots,pcs\n"))
		if err != nil {
			t.Fatal(err)
		}
		if len(rows) != 0 || len(bad) != 1 || bad[0].Line != 1 {
			t.Fatalf("rows=%+v bad=%+v", rows, bad)
		}
	})
}

package main

import (
	"errors"
	"fmt"
)

// ErrNoPackSize is returned for a SKU that has no pack size configured.
var ErrNoPackSize = errors.New("sku has no pack size set")

// PackSizes says how many pieces are in a box and how many boxes are on a pallet, for one SKU.
type PackSizes struct {
	PiecesPerBox   int
	BoxesPerPallet int
}

var piecesPer = map[string]func(PackSizes) int{
	"pcs":     func(PackSizes) int { return 1 },
	"boxes":   func(p PackSizes) int { return p.PiecesPerBox },
	"pallets": func(p PackSizes) int { return p.PiecesPerBox * p.BoxesPerPallet },
}

// Convert converts qty of a SKU between pcs, boxes and pallets using its pack sizes.
func Convert(sku string, sizes map[string]PackSizes, qty int, from, to string) (int, error) {
	pack, ok := sizes[sku]
	if !ok || pack.PiecesPerBox == 0 || pack.BoxesPerPallet == 0 {
		return 0, fmt.Errorf("convert %s: %w", sku, ErrNoPackSize)
	}

	fromN, okFrom := piecesPer[from]
	toN, okTo := piecesPer[to]
	if !okFrom || !okTo {
		return 0, fmt.Errorf("convert %s: unknown unit %q or %q", sku, from, to)
	}

	pieces := qty * fromN(pack)
	per := toN(pack)
	if pieces%per != 0 {
		return 0, fmt.Errorf("convert %s: %d %s is not a whole number of %s", sku, qty, from, to)
	}

	return pieces / per, nil
}

package main

import (
	"errors"
	"testing"
)

func TestConvert(t *testing.T) {
	t.Parallel()

	sizes := map[string]PackSizes{"BOLT-M6": {PiecesPerBox: 50, BoxesPerPallet: 40}}

	cases := []struct {
		name     string
		qty      int
		from, to string
		want     int
	}{
		{"pcs to boxes", 150, "pcs", "boxes", 3},
		{"boxes to pallets", 80, "boxes", "pallets", 2},
		{"pallets to pcs", 1, "pallets", "pcs", 2000},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			got, err := Convert("BOLT-M6", sizes, tc.qty, tc.from, tc.to)
			if err != nil || got != tc.want {
				t.Fatalf("Convert = %d, %v; want %d", got, err, tc.want)
			}
		})
	}

	t.Run("missing pack size refused", func(t *testing.T) {
		t.Parallel()
		if _, err := Convert("NUT-M8", sizes, 1, "boxes", "pcs"); !errors.Is(err, ErrNoPackSize) {
			t.Fatalf("want ErrNoPackSize, got %v", err)
		}
	})

	t.Run("non whole result refused", func(t *testing.T) {
		t.Parallel()
		if _, err := Convert("BOLT-M6", sizes, 7, "pcs", "boxes"); err == nil {
			t.Fatal("want an error for 7 pcs in boxes of 50")
		}
	})
}

package lock

import (
	"errors"
	"fmt"
	"os"
	"strconv"
	"strings"
)

// Name is the lock file every stock-writing command takes first.
const Name = ".tarnbrook.lock"

// ErrHeld is returned when another process already holds the lock.
var ErrHeld = errors.New("stock table locked")

// Lock is a held stock-table lock.
type Lock struct{ path string }

// Acquire creates the lock file exclusively, recording this process's pid. If the file exists it
// returns ErrHeld naming the pid that holds it.
func Acquire(dir string) (*Lock, error) {
	path := dir + string(os.PathSeparator) + Name

	file, err := os.OpenFile(path, os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0o644)
	if errors.Is(err, os.ErrExist) {
		held, _ := os.ReadFile(path)
		pid, _ := strconv.Atoi(strings.TrimSpace(string(held)))
		return nil, fmt.Errorf("%w by pid %d", ErrHeld, pid)
	}
	if err != nil {
		return nil, fmt.Errorf("taking %s: %w", Name, err)
	}
	defer file.Close()

	if _, err := fmt.Fprintf(file, "%d\n", os.Getpid()); err != nil {
		return nil, fmt.Errorf("writing %s: %w", Name, err)
	}

	return &Lock{path: path}, nil
}

// Release removes the lock file.
func (l *Lock) Release() error {
	if err := os.Remove(l.path); err != nil && !errors.Is(err, os.ErrNotExist) {
		return fmt.Errorf("releasing %s: %w", Name, err)
	}
	return nil
}

package lock

import (
	"errors"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"testing"
)

func TestAcquire(t *testing.T) {
	t.Parallel()

	t.Run("creates lock with pid", func(t *testing.T) {
		t.Parallel()
		dir := t.TempDir()
		held, err := Acquire(dir)
		if err != nil {
			t.Fatal(err)
		}
		defer held.Release()
		body, err := os.ReadFile(filepath.Join(dir, Name))
		if err != nil || strings.TrimSpace(string(body)) != strconv.Itoa(os.Getpid()) {
			t.Fatalf("lock body %q, err %v", body, err)
		}
	})

	t.Run("held lock names pid", func(t *testing.T) {
		t.Parallel()
		dir := t.TempDir()
		if err := os.WriteFile(filepath.Join(dir, Name), []byte("4242\n"), 0o644); err != nil {
			t.Fatal(err)
		}
		_, err := Acquire(dir)
		if !errors.Is(err, ErrHeld) || !strings.Contains(err.Error(), "pid 4242") {
			t.Fatalf("want ErrHeld naming pid 4242, got %v", err)
		}
	})
}

func TestRelease(t *testing.T) {
	t.Parallel()

	t.Run("removes lock", func(t *testing.T) {
		t.Parallel()
		dir := t.TempDir()
		held, err := Acquire(dir)
		if err != nil {
			t.Fatal(err)
		}
		if err := held.Release(); err != nil {
			t.Fatal(err)
		}
		if _, err := os.Stat(filepath.Join(dir, Name)); !errors.Is(err, os.ErrNotExist) {
			t.Fatalf("lock still present: %v", err)
		}
	})

	t.Run("missing lock is ok", func(t *testing.T) {
		t.Parallel()
		held := &Lock{path: filepath.Join(t.TempDir(), Name)}
		if err := held.Release(); err != nil {
			t.Fatal(err)
		}
	})
}

